// Offline audit only. Does not create a live database, publish, or access Drive.
package main
import("bufio";"compress/gzip";"crypto/sha256";"encoding/hex";"encoding/json";"errors";"flag";"fmt";"io";"log";"os";"strings";"github.com/hugo90082/MarketDepth-VNext/vnext/internal/legacy";"github.com/hugo90082/MarketDepth-VNext/vnext/internal/model")
func digest(b []byte)string{h:=sha256.Sum256(b);return hex.EncodeToString(h[:])}
type record struct{Type string `json:"type"`;Format string `json:"format"`;Schema string `json:"schema"`;DatasetFormat string `json:"datasetFormat"`;DepthUnit string `json:"depthUnit"`;QuoteToUSDPolicy string `json:"quoteToUSDPolicy"`;TimestampUnit string `json:"timestampUnit"`;CadenceMs int64 `json:"cadenceMs"`;Assets json.RawMessage `json:"assets"`;DepthVenues []string `json:"depthVenues"`;DepthZonesBps [][]int `json:"depthZonesBps"`;Blocks int `json:"blocks"`;DepthRows int `json:"depthRows"`;Candles int `json:"candles"`;Complete bool `json:"complete"`;legacy.V66Block}
func manifestAssets(raw json.RawMessage)bool{var a []string;return json.Unmarshal(raw,&a)==nil&&strings.Join(a,",")=="BTC,ETH,SOL"}
func run(path,want,wantRaw string)error{
 f,e:=os.Open(path);if e!=nil{return e};defer f.Close();st,e:=f.Stat();if e!=nil||!st.Mode().IsRegular(){return errors.New("regular input required")};h:=sha256.New();if _,e=io.Copy(h,f);e!=nil{return e};if hex.EncodeToString(h.Sum(nil))!=want{return errors.New("source SHA mismatch")};if _,e=f.Seek(0,0);e!=nil{return e}
 gz,e:=gzip.NewReader(f);if e!=nil{return e};defer gz.Close();rh:=sha256.New();r:=bufio.NewReaderSize(io.TeeReader(gz,rh),64<<10);var line int64;counts:=map[string]int{};days:=map[string]map[string]int{};seen:=map[struct{Kind model.Kind;Key model.Key}]bool{};hash:=sha256.New();var header,block record;var bd,bc int;var finished bool;examples:=map[string]json.RawMessage{}
 checkBlock:=func()error{if block.ID!=""&&(bd!=block.DepthRows||bc!=block.Candles){return errors.New("block counts differ")};return nil}
 for {raw,e:=r.ReadBytes('\n');if e==io.EOF&&len(raw)==0{break};if e!=nil{return fmt.Errorf("truncated or invalid gzip/line: %w",e)};line++;if len(raw)>legacy.MaxRowBytes{return errors.New("line limit")};if finished{return errors.New("data after summary")};var x record;if e=json.Unmarshal(raw,&x);e!=nil{return e}
 switch x.Type{
 case "manifest":if line!=1||x.Format!="MARKETDEPTH_LOCAL_HISTORY_JSONL_V1"||x.Schema!="MD-SPOT-30S-USD-3"||x.DatasetFormat!="MARKET_DEPTH_USD_NOTIONAL_TRUSTED_COVERAGE_V2"||x.DepthUnit!="USD_NOTIONAL"||x.QuoteToUSDPolicy!="RAW_QUOTE_PRICE_ASSUMED_USD_1_TO_1_NO_FX"||x.TimestampUnit!="UTC_UNIX_MILLISECONDS"||x.CadenceMs!=60000||!manifestAssets(x.Assets)||strings.Join(x.DepthVenues,",")!="binance,coinbase,kraken,bitfinex"||fmt.Sprint(x.DepthZonesBps)!="[[0 100] [100 200] [200 300] [300 500] [500 750]]"{return errors.New("unexpected manifest")};header=x
 case "block":if line==1||x.ID==""||x.Revision<1{return errors.New("bad block")};if e=checkBlock();e!=nil{return e};block=x;bd=0;bc=0
 case "depth","candle":if block.ID==""{return errors.New("missing block")};rows,e:=legacy.MapV66Rows(raw,block.V66Block);if e!=nil{return fmt.Errorf("line %d: %w",line,e)};if x.Type=="depth"{bd++}else{bc++};ev:=legacy.Evidence{SourceSHA256:want,RawSHA256:digest(raw),Line:line,Adapter:legacy.V66Adapter};for _,row:=range rows{b,e:=json.Marshal(row);if e!=nil{return e};
 // MapV66Rows invokes model.Validate for every row. Strict candidate-envelope checks are sampled.
 c:=legacy.Candidate{Kind:row.Kind(),Key:row.Key(),Day:model.Day(row.Key().T),CanonicalJSON:b,SHA256:digest(b)}
 if counts[string(c.Kind)]<12||line%1000==0{checked,e:=legacy.ValidateCandidate(ev,row.Kind(),b);if e!=nil||checked.SHA256!=c.SHA256{return fmt.Errorf("line %d: candidate sample mismatch: %v",line,e)};counts["strict_candidate_samples"]++}
 k:=struct{Kind model.Kind;Key model.Key}{c.Kind,c.Key};if seen[k]{return fmt.Errorf("duplicate candidate %v",k)};seen[k]=true;counts[string(c.Kind)]++;if days[c.Day]==nil{days[c.Day]=map[string]int{}};days[c.Day][string(c.Kind)]++;fmt.Fprintf(hash,"%d\t%s\t%s\n",line,c.Kind,c.SHA256);key:=string(c.Kind);if _,ok:=examples[key];!ok{examples[key]=c.CanonicalJSON}}
 case "summary":if e=checkBlock();e!=nil{return e};if !x.Complete||x.Blocks!=header.Blocks||x.Blocks!=counts["block"]||x.DepthRows!=counts["depth"]||x.Candles!=counts["candle"]{return errors.New("summary count mismatch")};finished=true
 default:return errors.New("unknown record type")};counts[x.Type]++
 }
 if !finished||hex.EncodeToString(rh.Sum(nil))!=wantRaw||counts["spot_depth"]!=12*counts["depth"]||counts["futures_1m"]!=counts["candle"]{return errors.New("raw digest or mapped accounting mismatch")};st2,e:=f.Stat();if e!=nil||st2.Size()!=st.Size()||st2.ModTime()!=st.ModTime(){return errors.New("source changed")}
 return json.NewEncoder(os.Stdout).Encode(map[string]any{"status":"dry_run_only","mapping_approved":false,"source_sha256":want,"raw_sha256":wantRaw,"adapter":legacy.V66Adapter,"lines":line,"counts":counts,"unique_keys":len(seen),"unknown_availability":len(seen),"futures_10s":0,"days":days,"ordered_candidate_digest":hex.EncodeToString(hash.Sum(nil)),"examples":examples})
}
func main(){p:=flag.String("input","","immutable gzip");s:=flag.String("sha256","","verified compressed SHA256");r:=flag.String("raw-sha256","","verified raw SHA256");flag.Parse();if len(*s)!=64||len(*r)!=64{log.Fatal("both verified SHA256 values required")};if e:=run(*p,*s,*r);e!=nil{log.Fatal(e)}}
